1	package server
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"errors"
7		"sort"
8		"sync"
9		"time"
10	)
11	
12	// Lease and admission outcomes surfaced to the HTTP layer.
13	var (
14		errNotFound             = errors.New("instance not found")
15		errLeaseConflict        = errors.New("lease conflict")
16		errHealthDisabled       = errors.New("health check disabled")
17		errInvalidHealthReport  = errors.New("invalid health report")
18		errHealthReportConflict = errors.New("health report conflict")
19		errStaleHealthReport    = errors.New("stale health report")
20		errNoRoutableInstance   = errors.New("no routable instance")
21		errConcurrencyLimited   = errors.New("concurrency limited")
22		errCircuitOpen          = errors.New("circuit open")
23		errPermitNotFound       = errors.New("permit not found")
24		errInvalidCompletion    = errors.New("invalid completion")
25	)
26	
27	// Health statuses exposed in the public instance representation.
28	const (
29		healthDisabled  = "disabled"
30		healthHealthy   = "healthy"
31		healthUnhealthy = "unhealthy"
32	)
33	
34	// healthState tracks the optional health policy of an instance and the
35	// consecutive-report counters that drive transitions. The zero value is the
36	// disabled state: no policy, no reports accepted, always routable.
37	type healthState struct {
38		configured       bool
39		failureThreshold int
40		successThreshold int
41		status           string // healthHealthy or healthUnhealthy once configured
42	
43		consecutivePass int
44		consecutiveFail int
45		lastSequence    int64
46		lastStatusPass  bool
47		hasSequence     bool
48	}
49	
50	// Circuit breaker states of an instance with a circuitBreaker policy. The
51	// zero value is the unconfigured state: no policy, never blocked.
52	const (
53		circuitClosed   = "closed"
54		circuitOpen     = "open"
55		circuitHalfOpen = "half_open"
56	)
57	
58	// circuitState tracks the optional circuit breaker policy of an instance.
59	// Consecutive failed completions in the closed state open the circuit for
60	// openSeconds; afterwards a single probe permit decides whether the circuit
61	// closes again or reopens. The zero value is the unconfigured state, which
62	// keeps the pre-existing admission behaviour.
63	type circuitState struct {
64		configured       bool
65		failureThreshold int
66		openSeconds      int
67		state            string // circuitClosed, circuitOpen or circuitHalfOpen once configured
68	
69		consecutiveFail  int
70		openUntil        time.Time
71		probeOutstanding bool // a half-open probe permit is currently out
72	}
73	
74	// blockedFor reports whether the instance may not receive a new permit at
75	// now, lazily advancing an expired open circuit to half-open. probe is set
76	// when a permit granted now would be the half-open probe. Callers must hold
77	// r.mu.
78	func (c *circuitState) blockedFor(now time.Time) (blocked, probe bool) {
79		if !c.configured {
80			return false, false
81		}
82		switch c.state {
83		case circuitOpen:
84			if now.Before(c.openUntil) {
85				return true, false
86			}
87			c.state = circuitHalfOpen
88			return false, true
89		case circuitHalfOpen:
90			if c.probeOutstanding {
91				return true, false
92			}
93			return false, true
94		default: // circuitClosed
95			return false, false
96		}
97	}
98	
99	// exported fields are set once at registration; token and expiresAt are
100	// mutated under the registry lock.
101	type instance struct {
102		Service        string
103		Instance       string
104		Endpoint       string
105		Version        string
106		Zone           string
107		Weight         int
108		TTLSeconds     int
109		Metadata       map[string]string
110		MaxConcurrency int // zero means unbounded
111	
112		token     string
113		expiresAt time.Time
114		health    healthState
115		circuit   circuitState
116	}
117	
118	func (i *instance) live(now time.Time) bool { return now.Before(i.expiresAt) }
119	
120	// healthStatus is the public health representation: "disabled" when no
121	// health policy was registered, otherwise the current healthy/unhealthy
122	// state driven by reported check results.
123	func (i *instance) healthStatus() string {
124		if !i.health.configured {
125			return healthDisabled
126		}
127		return i.health.status
128	}
129	
130	// permit is one outstanding short-lived admission permit. It references the
131	// exact instance record it was granted against, so overwriting,
132	// deregistering or losing the lease of that record invalidates the permit
133	// immediately even though the permit itself has not yet expired.
134	type permit struct {
135		token     string
136		service   string
137		inst      *instance
138		expiresAt time.Time
139		probe     bool // granted as the half-open probe of inst's circuit
140	}
141	
142	// registry holds all live and expired-but-unpurged instances. Expiration is
143	// evaluated lazily against the caller's clock, so an expired instance can
144	// never reappear in snapshots or be revived by a stale lease token.
145	type registry struct {
146		mu        sync.Mutex
147		instances map[string]map[string]*instance // service -> instance name -> record
148		permits   map[string]*permit              // outstanding permits by opaque token
149		inUse     map[*instance]int               // unexpired permits counted per record
150	}
151	
152	func newRegistry() *registry {
153		return &registry{
154			instances: make(map[string]map[string]*instance),
155			permits:   make(map[string]*permit),
156			inUse:     make(map[*instance]int),
157		}
158	}
159	
160	// newLeaseToken mints a random opaque token. Lease and permit tokens share
161	// the shape but live in independent namespaces.
162	func newLeaseToken() string {
163		var b [16]byte
164		if _, err := rand.Read(b[:]); err != nil {
165			panic(err)
166		}
167		return hex.EncodeToString(b[:])
168	}
169	
170	// newPermitToken mints the unique opaque token identifying one permit.
171	func newPermitToken() string { return newLeaseToken() }
172	
173	// register inserts inst, replacing any previous record with the same name and
174	// minting a fresh lease token (the old token stops matching immediately). It
175	// returns a copy of the stored record and whether a live instance was
176	// overwritten.
177	func (r *registry) register(inst *instance, now time.Time) (instance, bool) {
178		r.mu.Lock()
179		defer r.mu.Unlock()
180		inst.token = newLeaseToken()
181		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
182		byName, ok := r.instances[inst.Service]
183		if !ok {
184			byName = make(map[string]*instance)
185			r.instances[inst.Service] = byName
186		}
187		overwritten := false
188		if prev, ok := byName[inst.Instance]; ok {
189			if prev.live(now) {
190				overwritten = true
191			}
192			// The replacement is a new instance: permits granted against the
193			// previous record stop being releasable and free its quota at once.
194			r.invalidatePermitsLocked(prev)
195		}
196		byName[inst.Instance] = inst
197		return *inst, overwritten
198	}
199	
200	// renew extends the lease of a live instance whose current token matches.
201	func (r *registry) renew(service, name, token string, now time.Time) error {
202		r.mu.Lock()
203		defer r.mu.Unlock()
204		inst := r.lookupLocked(service, name, now)
205		if inst == nil {
206			return errNotFound
207		}
208		if token == "" || token != inst.token {
209			return errLeaseConflict
210		}
211		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
212		return nil
213	}
214	
215	// reportHealth applies one health report to a live instance. bodyOK reports
216	// whether the request body decoded and validated; it is checked only after
217	// existence, token and policy so those errors take precedence. Reports never
218	// extend the lease. Sequence handling: a strictly larger sequence advances
219	// state; the same sequence with the same status is an idempotent no-op, with
220	// a different status a conflict; a smaller sequence is stale.
221	func (r *registry) reportHealth(service, name, token string, bodyOK bool, seq int64, pass bool, now time.Time) error {
222		r.mu.Lock()
223		defer r.mu.Unlock()
224		inst := r.lookupLocked(service, name, now)
225		if inst == nil {
226			return errNotFound
227		}
228		if token == "" || token != inst.token {
229			return errLeaseConflict
230		}
231		if !inst.health.configured {
232			return errHealthDisabled
233		}
234		if !bodyOK {
235			return errInvalidHealthReport
236		}
237		h := &inst.health
238		if h.hasSequence {
239			if seq < h.lastSequence {
240				return errStaleHealthReport
241			}
242			if seq == h.lastSequence {
243				if pass == h.lastStatusPass {
244					return nil
245				}
246				return errHealthReportConflict
247			}
248		}
249		h.hasSequence = true
250		h.lastSequence = seq
251		h.lastStatusPass = pass
252		if pass {
253			h.consecutivePass++
254			h.consecutiveFail = 0
255			if h.consecutivePass >= h.successThreshold {
256				h.status = healthHealthy
257			}
258		} else {
259			h.consecutiveFail++
260			h.consecutivePass = 0
261			if h.consecutiveFail >= h.failureThreshold {
262				h.status = healthUnhealthy
263			}
264		}
265		return nil
266	}
267	
268	// deregister removes a live instance whose current token matches.
269	func (r *registry) deregister(service, name, token string, now time.Time) error {
270		r.mu.Lock()
271		defer r.mu.Unlock()
272		inst := r.lookupLocked(service, name, now)
273		if inst == nil {
274			return errNotFound
275		}
276		if token == "" || token != inst.token {
277			return errLeaseConflict
278		}
279		r.invalidatePermitsLocked(inst)
280		delete(r.instances[service], name)
281		if len(r.instances[service]) == 0 {
282			delete(r.instances, service)
283		}
284		return nil
285	}
286	
287	// lookupLocked returns the live record or nil; expired records are treated as
288	// absent. Callers must hold r.mu.
289	func (r *registry) lookupLocked(service, name string, now time.Time) *instance {
290		inst := r.instances[service][name]
291		if inst == nil || !inst.live(now) {
292			return nil
293		}
294		return inst
295	}
296	
297	// snapshot returns copies of the live instances of service matching the
298	// version/zone filters (empty string disables a filter), sorted by instance
299	// name. Unhealthy instances are excluded from routing and discovery; only
300	// healthy or health-disabled instances appear. Copies are taken under the
301	// lock so callers can read them race-free.
302	func (r *registry) snapshot(service, version, zone string, now time.Time) []instance {
303		r.mu.Lock()
304		defer r.mu.Unlock()
305		var out []instance
306		for _, inst := range r.instances[service] {
307			if !inst.live(now) {
308				continue
309			}
310			if inst.health.configured && inst.health.status == healthUnhealthy {
311				continue
312			}
313			if version != "" && inst.Version != version {
314				continue
315			}
316			if zone != "" && inst.Zone != zone {
317				continue
318			}
319			out = append(out, *inst)
320		}
321		sort.Slice(out, func(a, b int) bool { return out[a].Instance < out[b].Instance })
322		return out
323	}
324	
325	// dropPermitLocked removes one permit and releases the quota it occupied on
326	// its instance. Callers must hold r.mu.
327	func (r *registry) dropPermitLocked(p *permit) {
328		delete(r.permits, p.token)
329		if n := r.inUse[p.inst] - 1; n > 0 {
330			r.inUse[p.inst] = n
331		} else {
332			delete(r.inUse, p.inst)
333		}
334	}
335	
336	// prunePermitsLocked discards every permit that is no longer valid at now:
337	// permits past their own expiry and permits bound to an instance whose lease
338	// has expired. Overwritten and deregistered instances are removed eagerly by
339	// their callers. An expired probe permit re-opens its circuit. Callers must
340	// hold r.mu.
341	func (r *registry) prunePermitsLocked(now time.Time) {
342		for token, p := range r.permits {
343			if !now.Before(p.expiresAt) || !p.inst.live(now) {
344				delete(r.permits, token)
345				if n := r.inUse[p.inst] - 1; n > 0 {
346					r.inUse[p.inst] = n
347				} else {
348					delete(r.inUse, p.inst)
349				}
350				r.reopenIfProbeLocked(p, now)
351			}
352		}
353	}
354	
355	// reopenIfProbeLocked re-opens the circuit when a half-open probe permit
356	// ends without a completion outcome (released or expired). Callers must hold
357	// r.mu.
358	func (r *registry) reopenIfProbeLocked(p *permit, now time.Time) {
359		c := &p.inst.circuit
360		if c.configured && p.probe && c.state == circuitHalfOpen {
361			c.state = circuitOpen
362			c.probeOutstanding = false
363			c.openUntil = now.Add(time.Duration(c.openSeconds) * time.Second)
364		}
365	}
366	
367	// invalidatePermitsLocked releases every outstanding permit bound to inst.
368	// Overwriting or deregistering an instance invalidates its old permits
369	// immediately and gives the quota back. Callers must hold r.mu.
370	func (r *registry) invalidatePermitsLocked(inst *instance) {
371		for token, p := range r.permits {
372			if p.inst != inst {
373				continue
374			}
375			delete(r.permits, token)
376			if n := r.inUse[inst] - 1; n > 0 {
377				r.inUse[inst] = n
378			} else {
379				delete(r.inUse, inst)
380			}
381		}
382	}
383	
384	// acquiredPermit is the result of a successful admission: a copy of the
385	// chosen instance together with the opaque token and its expiry.
386	type acquiredPermit struct {
387		inst      instance
388		token     string
389		expiresAt time.Time
390	}
391	
392	// acquire atomically selects an instance for key and occupies one permit
393	// slot on it. Candidates are the live, non-unhealthy instances of service
394	// matching the version/zone filters, ranked by the same weighted rendezvous
395	// score used by resolve, best first; the first-ranked candidate with a free
396	// slot wins. Unbounded instances (MaxConcurrency == 0) always admit.
397	// Instances whose circuit is open, or half-open with a probe already out,
398	// are skipped in rank order; a half-open circuit grants its single probe
399	// permit to the first acquire that reaches it. The lookup and the occupancy
400	// happen under one lock, so the number of valid permits can never exceed an
401	// instance's quota. It returns errNoRoutableInstance when the filter matches
402	// nothing, errCircuitOpen when every match is blocked only by its circuit,
403	// and errConcurrencyLimited when every circuit-passing match is at capacity.
404	func (r *registry) acquire(service, key, version, zone string, ttl time.Duration, now time.Time) (acquiredPermit, error) {
405		r.mu.Lock()
406		defer r.mu.Unlock()
407		r.prunePermitsLocked(now)
408	
409		var candidates []*instance
410		for _, inst := range r.instances[service] {
411			if !inst.live(now) {
412				continue
413			}
414			if inst.health.configured && inst.health.status == healthUnhealthy {
415				continue
416			}
417			if version != "" && inst.Version != version {
418				continue
419			}
420			if zone != "" && inst.Zone != zone {
421				continue
422			}
423			candidates = append(candidates, inst)
424		}
425		if len(candidates) == 0 {
426			return acquiredPermit{}, errNoRoutableInstance
427		}
428		// Rank by descending rendezvous score; the instance name breaks the
429		// measure-zero tie exactly as selectInstance does.
430		sort.Slice(candidates, func(a, b int) bool {
431			sa := rendezvousScore(key, candidates[a].Instance, candidates[a].Weight)
432			sb := rendezvousScore(key, candidates[b].Instance, candidates[b].Weight)
433			if sa != sb {
434				return sa > sb
435			}
436			return candidates[a].Instance < candidates[b].Instance
437		})
438	
439		// Drop candidates blocked by their circuit, keeping rank order.
440		type eligible struct {
441			inst  *instance
442			probe bool
443		}
444		var passing []eligible
445		for _, cand := range candidates {
446			blocked, probe := cand.circuit.blockedFor(now)
447			if !blocked {
448				passing = append(passing, eligible{inst: cand, probe: probe})
449			}
450		}
451		if len(passing) == 0 {
452			return acquiredPermit{}, errCircuitOpen
453		}
454	
455		var chosen *eligible
456		for i := range passing {
457			cand := passing[i].inst
458			if cand.MaxConcurrency == 0 || r.inUse[cand] < cand.MaxConcurrency {
459				chosen = &passing[i]
460				break
461			}
462		}
463		if chosen == nil {
464			return acquiredPermit{}, errConcurrencyLimited
465		}
466	
467		token := newPermitToken()
468		for {
469			if _, taken := r.permits[token]; !taken {
470				break
471			}
472			token = newPermitToken()
473		}
474		expiresAt := now.Add(ttl)
475		r.permits[token] = &permit{
476			token:     token,
477			service:   service,
478			inst:      chosen.inst,
479			expiresAt: expiresAt,
480			probe:     chosen.probe,
481		}
482		r.inUse[chosen.inst]++
483		if chosen.probe {
484			chosen.inst.circuit.probeOutstanding = true
485		}
486		return acquiredPermit{inst: *chosen.inst, token: token, expiresAt: expiresAt}, nil
487	}
488	
489	// release releases a valid permit granted for service. Unknown tokens,
490	// expired permits, tokens bound to another service and permits invalidated
491	// by overwrite, deregistration or lease expiry all return errPermitNotFound.
492	// Releasing a half-open probe permit re-opens its circuit.
493	func (r *registry) release(service, token string, now time.Time) error {
494		r.mu.Lock()
495		defer r.mu.Unlock()
496		r.prunePermitsLocked(now)
497		p, ok := r.permits[token]
498		if !ok || p.service != service {
499			return errPermitNotFound
500		}
501		r.dropPermitLocked(p)
502		r.reopenIfProbeLocked(p, now)
503		return nil
504	}
505	
506	// complete settles a valid permit granted for service with a success or
507	// failure outcome, freeing its slot and invalidating the token. Existence
508	// and service checks run before the body validation so errPermitNotFound
509	// takes precedence, matching the health-report error ordering. Completions
510	// drive the circuit of the permit's instance: in the closed state a failure
511	// extends the consecutive-failure streak (opening the circuit at the
512	// threshold) and a success resets it; a probe completion closes the circuit
513	// on success and re-opens it on failure; completions while the circuit is
514	// open only free the slot.
515	func (r *registry) complete(service, token string, bodyOK, success bool, now time.Time) error {
516		r.mu.Lock()
517		defer r.mu.Unlock()
518		r.prunePermitsLocked(now)
519		p, ok := r.permits[token]
520		if !ok || p.service != service {
521			return errPermitNotFound
522		}
523		if !bodyOK {
524			return errInvalidCompletion
525		}
526		r.dropPermitLocked(p)
527		c := &p.inst.circuit
528		if !c.configured {
529			return nil
530		}
531		switch {
532		case p.probe:
533			// The half-open probe decides the circuit on its own.
534			c.probeOutstanding = false
535			if success {
536				c.state = circuitClosed
537				c.consecutiveFail = 0
538			} else {
539				c.state = circuitOpen
540				c.openUntil = now.Add(time.Duration(c.openSeconds) * time.Second)
541			}
542		case c.state == circuitClosed:
543			if success {
544				c.consecutiveFail = 0
545			} else {
546				c.consecutiveFail++
547				if c.consecutiveFail >= c.failureThreshold {
548					c.state = circuitOpen
549					c.consecutiveFail = 0
550					c.openUntil = now.Add(time.Duration(c.openSeconds) * time.Second)
551				}
552			}
553		}
554		// Open and (non-probe) half-open completions only free the slot.
555		return nil
556	}
