1	package server
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/url"
9		"regexp"
10		"time"
11		"unicode/utf8"
12	)
13	
14	// leaseHeader carries the lease token on heartbeat and deregister requests.
15	const leaseHeader = "X-Meshcore-Lease"
16	
17	// namePattern constrains service and instance names: 1-64 ASCII letters,
18	// digits, dots, underscores or hyphens.
19	var namePattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)
20	
21	func validName(s string) bool { return namePattern.MatchString(s) }
22	
23	type healthPolicyRequest struct {
24		FailureThreshold *int `json:"failureThreshold"`
25		SuccessThreshold *int `json:"successThreshold"`
26	}
27	
28	type circuitBreakerRequest struct {
29		FailureThreshold *int `json:"failureThreshold"`
30		OpenSeconds      *int `json:"openSeconds"`
31	}
32	
33	type registerRequest struct {
34		Endpoint       string                 `json:"endpoint"`
35		Version        string                 `json:"version"`
36		Zone           string                 `json:"zone"`
37		Weight         int                    `json:"weight"`
38		TTLSeconds     int                    `json:"ttlSeconds"`
39		Metadata       map[string]string      `json:"metadata"`
40		HealthPolicy   *healthPolicyRequest   `json:"healthPolicy"`
41		MaxConcurrency *int                   `json:"maxConcurrency"`
42		CircuitBreaker *circuitBreakerRequest `json:"circuitBreaker"`
43	}
44	
45	func (r *registerRequest) valid() bool {
46		if r.Endpoint == "" || r.Version == "" || r.Zone == "" {
47			return false
48		}
49		if r.Weight < 1 || r.Weight > 100 || r.TTLSeconds < 1 || r.TTLSeconds > 300 {
50			return false
51		}
52		if r.MaxConcurrency != nil && (*r.MaxConcurrency < 1 || *r.MaxConcurrency > 10000) {
53			return false
54		}
55		for k, v := range r.Metadata {
56			if k == "" || v == "" {
57				return false
58			}
59		}
60		if r.HealthPolicy != nil {
61			p := r.HealthPolicy
62			if p.FailureThreshold == nil || p.SuccessThreshold == nil {
63				return false
64			}
65			if *p.FailureThreshold < 1 || *p.FailureThreshold > 10 ||
66				*p.SuccessThreshold < 1 || *p.SuccessThreshold > 10 {
67				return false
68			}
69		}
70		if r.CircuitBreaker != nil {
71			cb := r.CircuitBreaker
72			if cb.FailureThreshold == nil || cb.OpenSeconds == nil {
73				return false
74			}
75			if *cb.FailureThreshold < 1 || *cb.FailureThreshold > 20 ||
76				*cb.OpenSeconds < 1 || *cb.OpenSeconds > 300 {
77				return false
78			}
79		}
80		return true
81	}
82	
83	// instanceView is the public representation of a registered instance. The
84	// lease token is deliberately excluded; it only appears in registerResponse.
85	// MaxConcurrency is omitted for instances registered without a cap, where
86	// concurrency is unbounded.
87	type instanceView struct {
88		Service        string            `json:"service"`
89		Instance       string            `json:"instance"`
90		Endpoint       string            `json:"endpoint"`
91		Version        string            `json:"version"`
92		Zone           string            `json:"zone"`
93		Weight         int               `json:"weight"`
94		TTLSeconds     int               `json:"ttlSeconds"`
95		Metadata       map[string]string `json:"metadata"`
96		ExpiresAt      string            `json:"expiresAt"`
97		HealthStatus   string            `json:"healthStatus"`
98		MaxConcurrency int               `json:"maxConcurrency,omitempty"`
99	}
100	
101	func viewOf(inst instance) instanceView {
102		return instanceView{
103			Service:        inst.Service,
104			Instance:       inst.Instance,
105			Endpoint:       inst.Endpoint,
106			Version:        inst.Version,
107			Zone:           inst.Zone,
108			Weight:         inst.Weight,
109			TTLSeconds:     inst.TTLSeconds,
110			Metadata:       inst.Metadata,
111			ExpiresAt:      inst.expiresAt.UTC().Format(time.RFC3339),
112			HealthStatus:   inst.healthStatus(),
113			MaxConcurrency: inst.MaxConcurrency,
114		}
115	}
116	
117	type registerResponse struct {
118		instanceView
119		LeaseToken string `json:"leaseToken"`
120	}
121	
122	type discoveryResponse struct {
123		Service   string         `json:"service"`
124		Instances []instanceView `json:"instances"`
125	}
126	
127	type resolveResponse struct {
128		Service  string       `json:"service"`
129		Key      string       `json:"key"`
130		Instance instanceView `json:"instance"`
