	if len(instances) != 1 || instances[0].RateLimit == nil ||
		instances[0].RateLimit.RequestsPerSecond != 5 || instances[0].RateLimit.Burst != 7 {
		t.Fatalf("discovery after invalid overwrite: %+v", instances)
	}
